 30		\[
 31			\mathcal T^{\mathrm{ld}} = \{\mathsf{Point}, \mathsf{ALine}, \mathsf{DLine}\}\;,
 32		\]
 33		and the distribution over type pairs $(t_{\mathrm A}, t_{\mathrm B})$ is uniform over $\mathcal T^{\mathrm{ld}} \times \mathcal T^{\mathrm{ld}}$. The ambient space is the direct sum $V = V_X \oplus V_I \oplus V_V$ of three register subspaces: the \emph{point register} $V_X \cong \F_q^m$, the \emph{coordinate register} $V_I \cong \F_q$, and the \emph{direction register} $V_V \cong \F_q^m$. Elements of $V$ are identified with triples $(u,s,v) \in \F_q^m \times \F_q \times \F_q^m$. The question distribution and the win predicate of $\mathfrak{G}^{\mathrm{ld}}$ are specified in Definitions~\ref{def:ld-question-distribution} and~\ref{def:ld-win-predicate} below.
 34	\end{definition}
